import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { ALL_CODES, CamelotHubPage, camelotHubMeta } from "@/components/songs/CamelotHubPage";
import { HUB_PAGE_SIZE } from "@/components/songs/HubPagination";
import { countSongsByCamelotCode } from "@/lib/server/link-analysis";

// /songs/camelot/<code>/page/<n> — pages 2+ of a Camelot hub. Exists for crawl
// reach: see components/songs/HubPagination.tsx.
// Frozen until the next deploy (see lib/server/catalog.ts): built at deploy
// time, never regenerated by traffic, so crawlers can't cost ISR writes.
export const revalidate = false;
export const dynamicParams = false;

// Exactly the pages that have songs on them (see the key-hub twin of this
// file): anything else is a static 404 under dynamicParams = false.
export async function generateStaticParams() {
  const params: { code: string; n: string }[] = [];
  for (const code of ALL_CODES) {
    const pages = Math.ceil((await countSongsByCamelotCode(code)) / HUB_PAGE_SIZE);
    for (let n = 2; n <= pages; n++) params.push({ code: code.toLowerCase(), n: String(n) });
  }
  return params;
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ code: string; n: string }>;
}): Promise<Metadata> {
  const { code, n } = await params;
  const page = Number(n);
  const meta = Number.isInteger(page) && page > 1 ? camelotHubMeta(code, page) : null;
  if (!meta) return { title: "Not found | TuneBad", robots: { index: false, follow: true } };
  return {
    title: meta.title,
    description: meta.description,
    alternates: { canonical: meta.canonical },
    openGraph: { url: meta.canonical, title: meta.title },
  };
}

export default async function Page({ params }: { params: Promise<{ code: string; n: string }> }) {
  const { code, n } = await params;
  const page = Number(n);
  // Page 1 has its own canonical URL; reject junk like /page/0 or /page/abc.
  if (!Number.isInteger(page) || page < 2) notFound();
  return <CamelotHubPage code={code} page={page} />;
}
